CALL {
  WITH a
  OPTIONAL MATCH (a)-[r]-(n:__Entity__)
  RETURN collect(DISTINCT CASE WHEN n IS NULL THEN null ELSE {relationship: type(r), related: n.name} END) AS relationships_a
}
CALL {
  WITH b
  OPTIONAL MATCH (b)-[r]-(n:__Entity__)
  RETURN collect(DISTINCT CASE WHEN n IS NULL THEN null ELSE {relationship: type(r), related: n.name} END) AS relationships_b
}
CALL {
