  RETURN collect(DISTINCT CASE WHEN s IS NULL THEN null ELSE {entity: s.name, case1_relationship: type(ra), case2_relationship: type(rb)} END) AS shared_connections
}
CALL {
  WITH a, b
  OPTIONAL MATCH (a)-[r]-(b)
  RETURN collect(DISTINCT type(r)) AS direct_relationships
}
RETURN a.name AS case1, relationships_a AS case1_relationships,
